package br.com.admeclesial.domain.financeiro;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="parcela_a_pagar",schema="adm_eclesial") public class ParcelaAPagar { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @Column(name="conta_a_pagar_id",nullable=false) Long contaAPagarId; @Column(nullable=false) Integer numero; @Column(nullable=false) LocalDate vencimento; @Column(nullable=false,precision=15,scale=2) BigDecimal valor; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) StatusParcelaAPagar status; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();} public Long getId(){return id;} public UUID getUuid(){return uuid;} public Long getContaAPagarId(){return contaAPagarId;} public Integer getNumero(){return numero;} public LocalDate getVencimento(){return vencimento;} public BigDecimal getValor(){return valor;} public StatusParcelaAPagar getStatus(){return status;} public void setContaAPagarId(Long v){contaAPagarId=v;} public void setNumero(Integer v){numero=v;} public void setVencimento(LocalDate v){vencimento=v;} public void setValor(BigDecimal v){valor=v;} public void setStatus(StatusParcelaAPagar v){status=v;} }